#!/usr/bin/env python3
import sys


def main():
    flags = []
    filepath = None
    args = sys.argv[1:]

    while args:
        if args[0].startswith('-') and args[0] != '-':
            flags.extend(list(args[0][1:]))
            args = args[1:]
        else:
            filepath = args[0]
            args = []

    # Default: show all three
    if not flags:
        flags = ['l', 'w', 'c']

    # Validate and deduplicate while preserving first-seen order, but enforce fixed output order
    seen = set()
    unique = []
    for f in flags:
        if f not in ('l', 'w', 'c'):
            print(f"wc: invalid option: -{f}", file=sys.stderr)
            sys.exit(1)
        if f not in seen:
            seen.add(f)
            unique.append(f)

    if filepath is None or filepath == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, 'rb') as fh:
            data = fh.read()

    lines = data.count(b'\n') + (1 if data and not data.endswith(b'\n') else 0)
    words = len(data.split())
    chars = len(data)

    counts = {'l': lines, 'w': words, 'c': chars}
    result = [str(counts[f]) for f in ('l', 'w', 'c') if f in seen]
    print(' '.join(result))


if __name__ == '__main__':
    main()

